import {updateMap} from './maps.mjs';
import {LOCATIONS,STATUSES,money,localDate,tomorrow,initialState,searchRides,bookRide,cancelBooking,advanceBooking,offerRide,removeOffer} from './core.mjs';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const KEY='platoride-browser-demo-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState();let storageWarning=false;try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.rides)&&Array.isArray(saved.bookings)&&saved.rides.every(r=>LOCATIONS.includes(r.from)&&LOCATIONS.includes(r.to)&&['shared','cab'].includes(r.service)&&Number.isFinite(r.price)&&Number.isInteger(r.seats)&&Number.isInteger(r.capacity)&&typeof r.departure==='string')&&saved.bookings.every(b=>typeof b.id==='string'&&typeof b.departure==='string'&&Number.isFinite(b.total))){state=saved;}}catch{storageWarning=true;}
let query={from:'Baner',to:'Hinjewadi',date:tomorrow(),seats:1,service:'shared'};let chosenRide=null;let confirmCallback=null;let toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Your changes last only for this visit.');}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function dateLabel(value){const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('en-IN',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(date):'Date unavailable';}
function timeLabel(value){return new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit'}).format(new Date(value));}
function initials(name){return name.split(' ').slice(0,2).map(n=>n[0]).join('');}
function empty(title,text,action=''){return `<div class="empty-state"><div class="empty-symbol" aria-hidden="true">↗</div><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function showView(name){if(!$('#view-'+name))return;$$('.view').forEach(v=>v.hidden=v.id!=='view-'+name);$$('.nav-button').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);if(b.dataset.view===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});renderSecondary();window.scrollTo({top:0,behavior:'instant'});const heading=$('#view-'+name+' h1');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}
function renderResults(){
 updateMap(query);
 let rides=[];try{rides=searchRides(state,query);$('#search-error').textContent='';}catch(e){$('#search-error').textContent=e.message;}
 $('#route-summary').innerHTML=`<span class="eyebrow">${query.service==='cab'?'A CAB OF YOUR OWN':'ONE ROUTE. MORE CONNECTION.'}</span><div class="route-line"><span>${esc(query.from)}</span><span aria-hidden="true">→</span><span>${esc(query.to)}</span></div><p>${esc(query.date)} · ${query.seats} passenger${query.seats>1?'s':''} · ${query.service==='cab'?'Whole-car sample fares':'Shared sample rides'}</p>`;
 $('#result-count').textContent=`${rides.length} result${rides.length!==1?'s':''}`;
 $('#results').innerHTML=rides.length?rides.map(r=>`<article class="ride-card"><div class="ride-card-header"><div class="avatar">${r.service==='cab'?'PR':esc(initials(r.host))}</div><div><strong>${esc(r.service==='cab'?r.vehicle:r.host)}</strong><small>${r.owned?'Your local offer':r.service==='cab'?'Sample cab · private vehicle':'Sample host · shared ride'}</small></div><div class="fare">${money(r.price)}<small>${r.service==='cab'?'whole car':'per seat'}</small></div></div><div class="ride-meta"><span>${esc(timeLabel(r.departure))}</span><span>${r.seats} ${r.service==='cab'?'passenger capacity':'seats left'}</span><span>${esc(r.vehicle)}</span></div><div class="ride-card-bottom"><p>${r.service==='cab'?'Only your group travels':'Share the route and the cost'}</p><button class="button dark" data-book="${esc(r.id)}" ${r.owned?'disabled':''}>${r.owned?'Your offer':'View ride ↗'}</button></div></article>`).join(''):empty('No matching journeys yet.','Try Baner to Hinjewadi tomorrow, fewer passengers, or another ride type.');
}
const labels={confirmed:'Confirmed',arriving:'Driver arriving',in_progress:'Trip in progress',completed:'Completed',cancelled:'Cancelled'};
function renderSecondary(){
 $('#trips').innerHTML=state.bookings.length?state.bookings.map(b=>`<article class="panel trip-card"><div class="results-top"><span class="tag ${esc(b.status)}">${esc(labels[b.status]||b.status)} · Demo</span><span>${esc(b.id)}</span></div><div class="trip-route">${esc(b.from)} → ${esc(b.to)}</div><p>${esc(dateLabel(b.departure))} · ${b.passengers} passenger${b.passengers>1?'s':''} · ${b.service==='cab'?'Private cab':'Shared ride'}</p><p>${esc(b.vehicle)} · ${esc(b.host)} · <strong>${money(b.total)} sample total</strong></p>${b.status!=='cancelled'?`<div class="progress-steps">${STATUSES.map((s,i)=>`<span class="${i<=STATUSES.indexOf(b.status)?'done':''}">${esc(labels[s])}</span>`).join('')}</div>`:''}<div class="trip-actions">${!['cancelled','completed'].includes(b.status)?`<button class="button dark" data-advance="${esc(b.id)}">Simulate: ${esc(labels[STATUSES[STATUSES.indexOf(b.status)+1]])}</button>`:''}${['confirmed','arriving'].includes(b.status)?`<button class="button outline" data-cancel="${esc(b.id)}">Cancel booking</button>`:''}</div>${!['cancelled','completed'].includes(b.status)?'<p class="form-note">Trip progress changes only when you tap simulate. No driver is dispatched.</p>':''}</article>`).join(''):empty('Your next journey starts here.','Choose a sample shared ride or private cab to see your booking here.','<button class="button dark" data-view="ride">Find a ride ↗</button>');
 const offers=state.rides.filter(r=>r.owned);$('#my-offers').innerHTML=offers.length?offers.map(r=>`<article class="ride-card"><span class="tag">Local offer</span><div class="trip-route">${esc(r.from)} → ${esc(r.to)}</div><p class="form-note">${esc(dateLabel(r.departure))}<br>${esc(r.vehicle)} · ${r.seats} seats · ${money(r.price)} / seat</p><button class="button outline button-small" data-remove="${esc(r.id)}">Remove offer</button></article>`).join(''):empty('Make your first offer.','Your offered journeys will appear here.');
 $('#demo-trip-count').textContent=`${state.bookings.filter(b=>b.status==='completed').length} demo trips completed on this browser. Demo activity does not generate real environmental impact.`;
}
function review(id){chosenRide=state.rides.find(r=>r.id===id);if(!chosenRide)return;const r=chosenRide;const total=r.price*(r.service==='cab'?1:query.seats);$('#booking-content').innerHTML=`<span class="tag">${r.service==='cab'?'Private cab':'Shared ride'} · Sample booking</span><div class="trip-route">${esc(r.from)} → ${esc(r.to)}</div><p>${esc(dateLabel(r.departure))}<br>${esc(r.host)} · ${esc(r.vehicle)}</p><div class="price-breakdown"><div><span>${r.service==='cab'?'Whole-car fare':`${money(r.price)} × ${query.seats} seat${query.seats>1?'s':''}`}</span><span>${money(total)}</span></div><div><span>Demo platform fee</span><span>₹0</span></div><div class="total"><span>Sample total</span><span>${money(total)}</span></div></div><p>No charge will be made. This is a local demo, with no real driver or passenger connection.</p><label class="check-row"><input id="demo-consent" type="checkbox"><span>I understand this is a sample booking, not a real ride.</span></label><div id="booking-error" class="error-message" role="alert"></div><button class="button dark full-width" id="confirm-booking" disabled>Confirm demo booking ↗</button>`;$('#booking-dialog').showModal();}
function confirm(title,copy,label,callback){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-action').textContent=label;$('#keep-action').textContent='Go back';confirmCallback=callback;$('#confirm-dialog').showModal();}
function update(){save();renderResults();renderSecondary();}
for(const id of ['from','to','offer-from','offer-to']){$('#'+id).innerHTML=LOCATIONS.map(x=>`<option value="${x}">${x}</option>`).join('');}$('#to').value='Hinjewadi';$('#offer-to').value='Hinjewadi';$('#travel-date').value=query.date;$('#travel-date').min=localDate(new Date());$('#departure').value=query.date+'T09:00';$('#departure').min=localDate(new Date())+'T00:00';
$('#search-form').addEventListener('submit',e=>{e.preventDefault();query={from:$('#from').value,to:$('#to').value,date:$('#travel-date').value,seats:Number($('#seats').value),service:$('#service').value};renderResults();});
$('#offer-form').addEventListener('submit',e=>{e.preventDefault();try{offerRide(state,{from:$('#offer-from').value,to:$('#offer-to').value,departure:$('#departure').value,vehicle:$('#vehicle').value,seats:Number($('#offer-seats').value),price:Number($('#offer-price').value)});$('#offer-error').textContent='';update();toast('Your demo offer is saved in this browser.');}catch(error){$('#offer-error').textContent=error.message;}});
document.addEventListener('change',e=>{if(e.target.id==='demo-consent')$('#confirm-booking').disabled=!e.target.checked;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)showView(b.dataset.view);else if(b.dataset.book)review(b.dataset.book);else if(b.dataset.advance){try{advanceBooking(state,b.dataset.advance);update();toast('Demo trip stage updated.');}catch(err){toast(err.message);}}else if(b.dataset.cancel)confirm('Cancel this booking?','The demo seats will become available again. No fee will be charged.','Cancel booking',()=>{cancelBooking(state,b.dataset.cancel);update();toast('Demo booking cancelled.');});else if(b.dataset.remove)confirm('Remove your offer?','This removes the sample journey from this browser.','Remove offer',()=>{removeOffer(state,b.dataset.remove);update();toast('Demo offer removed.');});else if(b.id==='confirm-booking'){if(!$('#demo-consent').checked||!chosenRide)return;try{bookRide(state,chosenRide.id,query.seats);update();$('#booking-dialog').close();showView('trips');toast('Demo booking confirmed. No payment taken.');}catch(err){$('#booking-error').textContent=err.message;}}});
$('#close-booking').addEventListener('click',()=>$('#booking-dialog').close());$('#close-confirm').addEventListener('click',()=>$('#confirm-dialog').close());$('#keep-action').addEventListener('click',()=>$('#confirm-dialog').close());$('#confirm-action').addEventListener('click',()=>{try{confirmCallback?.();$('#confirm-dialog').close();}catch(err){toast(err.message);}});$('#reset-button').addEventListener('click',()=>confirm('Reset your demo?','This clears sample bookings and offered rides stored in this browser.','Reset demo',()=>{state=initialState();query={from:'Baner',to:'Hinjewadi',date:tomorrow(),seats:1,service:'shared'};$('#from').value=query.from;$('#to').value=query.to;$('#travel-date').value=query.date;$('#service').value=query.service;$('#seats').value='1';update();showView('ride');toast('Your demo is ready for a fresh start.');}));
renderResults();renderSecondary();if(storageWarning)toast('Browser storage could not be read. A fresh demo is running for this visit.');
